export const getGetMessagesIdMediaUrl = (id: string,
    params: GetMessagesIdMediaParams,) => {
  const normalizedParams = new URLSearchParams();

  Object.entries(params || {}).forEach(([key, value]) => {

    if (value !== undefined) {
      normalizedParams.append(key, value === null ? 'null' : String(value))
    }
  });

  const stringifiedParams = normalizedParams.toString();

  return stringifiedParams.length > 0 ? `http://localhost:3000/api/messages/${id}/media?${stringifiedParams}` : `http://localhost:3000/api/messages/${id}/media`
}

